# a regra da ordem do 4,44 em cada PARAGRAFO do ESTADO que traz o numero: tem de trazer o p calibrado e a linha dos 5 sigma
falhas = []
for par in txt.split("\n"):
    if z4 in par and "z_disc" in par.replace(" ", "") or ("%s da frase" % z4) in par:
        n = QV.normaliza(par)
        if not (re.search(r"5\s*(?:sigma|\u03c3)", n) and ("e-6" in n or p4.replace("−", "-") in n) and ("alcan" in n)):
            falhas.append(par[:140])
assert not falhas, ("regra da ordem do 4,44 no ESTADO", falhas[:3])
p = os.path.join(HERE, "ESTADO_V397.md")
if os.path.exists(p):
    os.replace(p, p + ".bak_" + time.strftime("%Y%m%d_%H%M%S") + "_c1")
